<script setup lang="ts">
withDefaults(defineProps<{name:string;alt:string;variant?:'spin'|'orbit'|'float'|'kenburns'|'parallax'|'morphMask'|'parts';position?:string;loading?:'lazy'|'eager'}>(),{variant:'float',position:'center',loading:'lazy'})
const el=ref<HTMLElement>();onMounted(()=>{const io=new IntersectionObserver(([e])=>el.value?.classList.toggle('running',!!e?.isIntersecting),{rootMargin:'48px'});if(el.value)io.observe(el.value);onBeforeUnmount(()=>io.disconnect())})
</script>
<template><div ref="el" class="motion-image" :class="`image-${variant}`" :style="{'--position':position}"><div class="image-mover"><picture><source type="image/avif" :srcset="`/images/${name}-640.avif 640w, /images/${name}-960.avif 960w, /images/${name}-1440.avif 1440w`" sizes="(max-width:768px) 100vw, 50vw"><img :src="`/images/${name}-960.webp`" :srcset="`/images/${name}-640.webp 640w, /images/${name}-960.webp 960w, /images/${name}-1440.webp 1440w`" sizes="(max-width:768px) 100vw, 50vw" :alt="alt" :loading="loading" width="960" height="960" :style="{objectPosition:position}"></picture></div><img v-if="variant==='morphMask'" class="mask-alternate" :src="`/images/${name}-960.webp`" alt="" aria-hidden="true" width="960" height="960" loading="lazy"><template v-if="variant==='parts'||variant==='orbit'"><div v-for="n in 3" :key="n" class="orbit-piece" :class="`piece-${n}`" aria-hidden="true"><img :src="`/images/${name}-640.webp`" alt="" width="640" height="640" loading="lazy"></div></template></div></template>
